    },
    filters: #"SYSTEM_SYSRULES_queryLogicalExpression"(
      operator: "AND",
      filters: {
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:f7d4a31b-036e-413a-b0bf-2215cb228832/c328359a-a4b1-488a-8324-7beafa21d9ae",
          operator: "=",
          value: if(
            a!isNullOrEmpty(index(pv!LLMMap, "departamento", null)),
            if(
              a!isNullOrEmpty(index(pv!ATRegion, "type", null)),
              tostring(pv!ATRegional.type),
              tostring(pv!ATRegion.type)
            ),
            index(pv!LLMMap, "departamento", null)
          )
        )
      },
      ignoreFiltersWithEmptyValues: true
    ),
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 1)
  ).data[#"urn:appian:record-field:v1:f7d4a31b-036e-413a-b0bf-2215cb228832/2bcca99a-defc-4dc8-9f9c-4d388bc30236"],
